  "Open the record": { de: "Datensatz öffnen", es: "Abrir el registro", ca: "Obrir el registre", zh: "打开该记录", hi: "रिकॉर्ड खोलें", ar: "فتح السجل", fr: "Ouvrir la fiche", bn: "রেকর্ডটি খুলুন", pt: "Abrir o registro", ru: "Открыть запись", ur: "ریکارڈ کھولیں", id: "Buka catatan", ja: "レコードを開く", pa: "ਰਿਕਾਰਡ ਖੋਲ੍ਹੋ", mr: "नोंद उघडा", te: "రికార్డును తెరవండి", tr: "Kaydı aç", ta: "பதிவைத் திற", vi: "Mở bản ghi", ha: "Buɗe bayanin", sw: "Fungua rekodi", tl: "Buksan ang record", ko: "레코드 열기", fa: "باز کردن رکورد", jv: "Bukak cathetan", it: "Apri il record", gu: "રેકોર્ડ ખોલો", th: "เปิดระเบียน" },
  "Open what this is timing": { de: "Öffnen, wofür die Zeit läuft", es: "Abrir aquello que se está cronometrando", ca: "Obrir allò que s'està cronometrant", zh: "打开正在计时的对象", hi: "जिस पर समय चल रहा है उसे खोलें", ar: "فتح ما يجري توقيته", fr: "Ouvrir ce qui est chronométré", bn: "যেটির সময় গোনা হচ্ছে সেটি খুলুন", pt: "Abrir o que está sendo cronometrado", ru: "Открыть то, для чего идет отсчет", ur: "جس پر وقت چل رہا ہے اسے کھولیں", id: "Buka yang sedang dihitung waktunya", ja: "計測中の対象を開く", pa: "ਜਿਸ ਉੱਤੇ ਸਮਾਂ ਚੱਲ ਰਿਹਾ ਹੈ ਉਸਨੂੰ ਖੋਲ੍ਹੋ", mr: "ज्याचा वेळ मोजला जात आहे ते उघडा", te: "దేనికి సమయం లెక్కిస్తున్నారో దాన్ని తెరవండి", tr: "Süre tutulan şeyi aç", ta: "எதற்கு நேரம் கணக்கிடப்படுகிறதோ அதைத் திற", vi: "Mở việc đang được bấm giờ", ha: "Buɗe abin da ake ƙidayar lokacinsa", sw: "Fungua kile kinachopimwa muda", tl: "Buksan ang tinitimingan nito", ko: "시간을 재고 있는 대상 열기", fa: "باز کردن چیزی که زمانش گرفته می‌شود", jv: "Bukak sing lagi diwaktoni", it: "Apri ciò che si sta cronometrando", gu: "જેનો સમય ગણાઈ રહ્યો છે તે ખોલો", th: "เปิดสิ่งที่กำลังจับเวลาอยู่" },
  "Open {name}": { de: "{name} öffnen", es: "Abrir {name}", ca: "Obrir {name}", zh: "打开 {name}", hi: "{name} खोलें", ar: "فتح {name}", fr: "Ouvrir {name}", bn: "{name} খুলুন", pt: "Abrir {name}", ru: "Открыть {name}", ur: "{name} کھولیں", id: "Buka {name}", ja: "{name} を開く", pa: "{name} ਖੋਲ੍ਹੋ", mr: "{name} उघडा", te: "{name} తెరవండి", tr: "{name} öğesini aç", ta: "{name} திற", vi: "Mở {name}", ha: "Buɗe {name}", sw: "Fungua {name}", tl: "Buksan ang {name}", ko: "{name} 열기", fa: "باز کردن {name}", jv: "Bukak {name}", it: "Apri {name}", gu: "{name} ખોલો", th: "เปิด {name}" },
  "Pick a role.": { de: "Wählen Sie eine Rolle.", es: "Elige un rol.", ca: "Tria un rol.", zh: "请选择一个角色。", hi: "एक भूमिका चुनें।", ar: "اختر دورا.", fr: "Choisissez un rôle.", bn: "একটি ভূমিকা বেছে নিন।", pt: "Escolha uma função.", ru: "Выберите роль.", ur: "ایک کردار چنیں۔", id: "Pilih peran.", ja: "役職を選んでください。", pa: "ਇੱਕ ਭੂਮਿਕਾ ਚੁਣੋ।", mr: "एक भूमिका निवडा.", te: "ఒక పాత్రను ఎంచుకోండి.", tr: "Bir rol seçin.", ta: "ஒரு பாத்திரத்தைத் தேர்ந்தெடுங்கள்.", vi: "Hãy chọn một vai trò.", ha: "Zaɓi matsayi.", sw: "Chagua jukumu.", tl: "Pumili ng tungkulin.", ko: "역할을 고르세요.", fa: "یک نقش انتخاب کنید.", jv: "Pilih peran.", it: "Scegli un ruolo.", gu: "એક ભૂમિકા પસંદ કરો.", th: "เลือกบทบาท" },
  "Pick an existing group or start a new one, then add the value.": { de: "Wählen Sie eine bestehende Gruppe oder legen Sie eine neue an, und fügen Sie dann den Wert hinzu.", es: "Elige un grupo existente o crea uno nuevo, y después añade el valor.", ca: "Tria un grup existent o crea'n un de nou, i després afegeix el valor.", zh: "选择一个已有的分组，或新建一个，然后添加这个值。", hi: "कोई मौजूदा समूह चुनें या नया शुरू करें, फिर वैल्यू जोड़ें।", ar: "اختر مجموعة موجودة أو أنشئ مجموعة جديدة، ثم أضف القيمة.", fr: "Choisissez un groupe existant ou créez-en un nouveau, puis ajoutez la valeur.", bn: "একটি বিদ্যমান গ্রুপ বেছে নিন বা নতুন একটি শুরু করুন, তারপর মানটি যোগ করুন।", pt: "Escolha um grupo existente ou crie um novo, depois adicione o valor.", ru: "Выберите существующую группу или создайте новую, затем добавьте значение.", ur: "کوئی موجودہ گروپ چنیں یا نیا بنائیں، پھر قدر شامل کریں۔", id: "Pilih grup yang sudah ada atau buat yang baru, lalu tambahkan nilainya.", ja: "既存のグループを選ぶか新しく作り、それから値を追加してください。", pa: "ਕੋਈ ਮੌਜੂਦਾ ਸਮੂਹ ਚੁਣੋ ਜਾਂ ਨਵਾਂ ਸ਼ੁਰੂ ਕਰੋ, ਫਿਰ ਮੁੱਲ ਜੋੜੋ।", mr: "अस्तित्वात असलेला गट निवडा किंवा नवीन सुरू करा, मग मूल्य जोडा.", te: "ఉన్న సమూహాన్ని ఎంచుకోండి లేదా కొత్తది మొదలుపెట్టండి, ఆపై విలువను జోడించండి.", tr: "Var olan bir grubu seçin ya da yeni bir tane başlatın, sonra değeri ekleyin.", ta: "ஏற்கனவே உள்ள ஒரு குழுவைத் தேர்ந்தெடுங்கள் அல்லது புதிதாகத் தொடங்குங்கள், பிறகு மதிப்பைச் சேர்க்கவும்.", vi: "Chọn một nhóm có sẵn hoặc tạo nhóm mới, rồi thêm giá trị.", ha: "Zaɓi rukunin da yake nan ko fara sabo, sannan ƙara ƙimar.", sw: "Chagua kikundi kilichopo au anzisha kipya, kisha ongeza thamani.", tl: "Pumili ng umiiral na grupo o gumawa ng bago, tapos idagdag ang halaga.", ko: "기존 그룹을 고르거나 새로 만든 뒤, 값을 추가하세요.", fa: "یک گروه موجود انتخاب کنید یا گروه تازه‌ای بسازید، سپس مقدار را اضافه کنید.", jv: "Pilih grup sing wis ana utawa gawe sing anyar, banjur tambahna nilaine.", it: "Scegli un gruppo esistente o creane uno nuovo, poi aggiungi il valore.", gu: "કોઈ હાલનું જૂથ પસંદ કરો અથવા નવું શરૂ કરો, પછી મૂલ્ય ઉમેરો.", th: "เลือกกลุ่มที่มีอยู่หรือสร้างกลุ่มใหม่ แล้วเพิ่มค่าเข้าไป" },
